insert into public.companies (slug,name) values ('tidemark-va','Tidemark VA'),('tidemark-therapy','Tidemark Therapy'),('mental-health-managed','Mental Health Managed') on conflict (slug) do nothing;
insert into public.permissions(key,description) values
('workspace.manage','Manage workspaces'),('users.invite','Invite users'),('audit_logs.view','View audit logs'),('clients.read','Read clients'),('clients.create','Create clients'),('clients.update','Update clients'),('clients.archive','Archive clients'),('invoices.read','Read invoices'),('invoices.create','Create invoices'),('invoices.update','Update invoices'),('payroll.read','Read payroll'),('payroll.create','Create payroll'),('payroll.update','Update payroll'),('payroll.approve','Approve payroll'),('credentials.read','Read credentials'),('credentials.update','Update credentials'),('reports.view','View reports'),('reports.export','Export reports'),('automation.manage','Manage automations') on conflict(key) do nothing;
insert into public.roles(key,name,is_system) values ('global_admin','Global Administrator',true),('company_admin','Company Administrator',true),('manager','Manager',true),('member','Member',true),('viewer','Viewer',true) on conflict do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.key in ('global_admin','company_admin') on conflict do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.key in ('clients.read','clients.create','clients.update','invoices.read','credentials.read','credentials.update','reports.view') where r.key='manager' on conflict do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.key in ('clients.read','invoices.read','credentials.read','reports.view') where r.key in ('member','viewer') on conflict do nothing;
insert into public.company_modules(company_id,module_key,enabled) select c.id,m.key,true from public.companies c cross join (values ('dashboard'),('crm'),('workspaces'),('calendar'),('documents'),('reports')) m(key) on conflict do nothing;
